    if (!OP_ID.test(data.operationId || '') || !Number.isSafeInteger(data.expectedRevision) || data.expectedRevision < 0) fail('invalid-operation', 400);
    d.operationId = data.operationId;
    d.expectedRevision = data.expectedRevision;
